INSERT INTO taxonomy_domains (slug, name, description, position) VALUES
  ('safety', 'Safety', 'Working safely: hazard controls, energy isolation, hazardous materials, protective equipment.', 1),
  ('production', 'Production', 'What everyone on a floor shares: reading prints and work instructions, shop math, moving material, controlled environments, traceability.', 2),
  ('machining', 'Machining', 'Cutting metal to size: manual and CNC machining, grinding, EDM, setup and programming.', 3),
  ('fabrication', 'Fabrication', 'Shaping and joining metal: welding, cutting, sheet metal, stamping, casting, additive manufacturing.', 4),
  ('materials', 'Materials', 'Changing what a material is or how its surface behaves: heat treatment, plating, coatings, composites.', 5),
  ('assembly', 'Assembly', 'Putting hardware together: fastening, sealing and bonding, fits and alignment.', 6),
  ('electronics', 'Electronics', 'Building electronics and wiring: soldering, board assembly, rework, harnesses and cabling.', 7),
  ('semiconductor', 'Semiconductor', 'Making chips: lithography, deposition, etch, wafer metrology, packaging, probe and test.', 8),
  ('battery', 'Battery and electric drive', 'Cells, modules and packs; motors and drive units.', 9),
  ('process', 'Process', 'Food, beverage and pharmaceutical processing: batching, filling, sterilisation, aseptic work, GMP.', 10),
  ('quality', 'Quality', 'Measuring and assuring: measurement tools, CMM, GD&T, inspection, quality systems, statistics.', 11),
  ('ndt', 'Nondestructive testing', 'Ultrasonic, radiographic, eddy current, magnetic particle, penetrant and visual methods.', 12),
  ('test', 'Test', 'Proving that a product works: electrical, functional, environmental and vehicle testing.', 13),
  ('maintenance', 'Maintenance', 'Keeping machines running: mechanical and electrical maintenance, fluid power, reliability.', 14),
  ('automation', 'Automation', 'Making machines run themselves: PLCs, robots, motion and drives, industrial networks, vision.', 15),
  ('engineering', 'Engineering', 'Designing parts and processes: CAD, design methods, analysis, manufacturing engineering.', 16);
